  "The services restart one after another and the database migrates. Screens may be unavailable for a few minutes. If a step fails, the previous images are put back. The database is not restored automatically: a backup taken before the update is kept, and an administrator can restore it.": "サービスが順に再起動し、データベースが移行されます。数分間、画面が利用できない場合があります。手順が失敗した場合は、以前のイメージに戻されます。データベースは自動では復元されません。更新前に作成したバックアップが保持され、管理者が復元できます。",
