  "The load file is out and waits for the SAP load. Once it is loaded in SAP, an approver or SAP Basis confirms it here; the next run then checks the records.": "ロードファイルは出力済みで、SAP への取り込みを待っています。SAP に取り込まれたら、承認者または SAP Basis がここで確認します。次回の実行でレコードがチェックされます。",
  "The load could not be confirmed.": "取り込みを確認できませんでした。",
  "Load file exported, {records} {records2, plural, one {record} other {records}}": "ロードファイルをエクスポート済み、{records} 件のレコード",
  "{filename}{sum}. Load it into SAP with the Migration Cockpit, then confirm the load on the batch.": "{filename}{sum}。Migration Cockpit で SAP に取り込み、その後バッチで取り込みを確認してください。",
  "Exported the load file of batch {label} as {filename}": "バッチ {label} のロードファイルを {filename} としてエクスポートしました",
