  "The match candidates could not be read.": "マッチ候補を読み込めませんでした。",
  "No pair of {label} records is waiting for a steward. Pairs appear when a match run scores two records between the review floor and the auto-merge score.": "スチュワードを待っている {label} のレコードペアはありません。マッチ実行で 2 件のレコードのスコアがレビュー下限と自動マージスコアの間になると、ペアが表示されます。",
