  "{accepted} suggested values for {id} are in your draft batch {draft_batch_id}. Nothing reaches SAP until an owner approves.": "{id} の提案値 {accepted} 件を下書きバッチ {draft_batch_id} に追加しました。オーナーが承認するまで SAP には何も反映されません。",
