  "Grouping by rule does not apply to a policy class or a past run": "ルール別のグループ化は、ポリシークラスや過去の実行には使えません",
  "As of run": "実行時点",
  "The fix sheet reads today's rows without a policy or a past run; clear them to export": "修正シートはポリシーや過去の実行を使わず現在の行を読み込みます。エクスポートするにはそれらを解除してください",
  "As it stood at run {when}; statuses are today's.": "{when} の実行時点の状態です。ステータスは現在のものです。",
  "New in run {b}: records failing a check they did not fail in run {a}.": "{b} の実行で新たに検出: {a} の実行では不合格でなかったチェックに不合格のレコードです。",
  "Counts on the chips are today's.": "チップの件数は現在のものです。",
  "Each object is read at its newest run up to then. Counts on the chips are today's.": "各オブジェクトはその時点までの最新の実行で読み込まれます。チップの件数は現在のものです。",
  "The history of this record could not be read.": "このレコードの履歴を読み込めませんでした。",
  "No run has measured this record yet, and nothing has been decided on it.": "このレコードを測定した実行はまだなく、判断も行われていません。",
  "Every run": "すべての実行",
  "{n} {n, plural, one {run} other {runs}} measured this record, {failing} with it failing. Values are as each run stored them; the work status is today's.": "{n} 回の実行がこのレコードを測定し、そのうち {failing} 回で失敗していました。値は各実行が保存したもので、作業ステータスは現在のものです。",
  "Runs of this record, scrollable": "このレコードの実行（スクロール可能）",
  "Values of the failing fields by run": "実行ごとの失敗項目の値",
  "Status today": "現在のステータス",
  "sandbox": "サンドボックス",
  "No rule failed this record in this run": "この実行ではこのレコードで失敗したルールはありません",
  "Not stored for this run": "この実行では保存されていません",
  "No work row in this run": "この実行には作業行がありません",
  "Decisions": "判断",
  "Nothing has been decided on this record yet.": "このレコードについてはまだ何も判断されていません。",
  "Sandbox: nothing leaves this deployment.": "サンドボックス: この環境から外へは何も出ません。",
  "Since {when}, by {who}.": "{when} から、{who} が開始。",
  "Since {when}.": "{when} から。",
  "Decisions land on the sandbox copy; notifications, webhooks, digests and write-backs are held back.": "判断はサンドボックスのコピーに記録されます。通知、Webhook、ダイジェスト、書き戻しは保留されます。",
  "Sandbox settings": "サンドボックスの設定",
  "Start with ? to ask in a sentence, such as ?critical vendors assigned to me due this week. The answer is a ledger filter you can see before it runs.": "? で始めると文章で質問できます（例: ?critical vendors assigned to me due this week）。回答は台帳のフィルターで、実行前に内容を確認できます。",
  "Ask in a sentence": "文章で質問",
  "Type a question after the ?, such as ?vendor bank data in ECC production, or ?overdue materials assigned to me.": "? の後に質問を入力してください（例: ?vendor bank data in ECC production、?overdue materials assigned to me）。",
  "The filter that will run": "実行されるフィルター",
  "The question could not be read. Try other words, or search without the ?.": "質問を読み込めませんでした。別の言葉を試すか、? を付けずに検索してください。",
  "Reading the question": "質問を読み込んでいます",
  "From the words: {phrase}": "語句: {phrase}",
  "No filter: Open shows the open work.": "フィルターなし: 開くと未完了の作業が表示されます。",
  "Not understood, left out of the filter: {words}": "理解できず、フィルターから除外: {words}",
  "The language model mapped some words onto the same filters; the filter above is still what runs.": "一部の語句は言語モデルが同じフィルターに対応付けました。実行されるのは上のフィルターです。",
  "Open in Work": "作業で開く",
  "Queue": "キュー",
