  "Prediction before you start": "開始前の予測",
  "Before you start the extraction": "抽出を開始する前に",
  "Before you start the analysis": "分析を開始する前に",
  "No prediction could be read. The run can still be started.": "予測を読み込めませんでした。実行は開始できます。",
  "{band}, {confidence}": "{band}、{confidence}",
  "Cost": "コスト",
  "{amount} ({low} to {high})": "{amount}（{low} から {high}）",
  "The cost model prices no run: set the run cost per hour or per million records under Settings": "コストモデルに実行の単価がありません。設定で 1 時間あたり、または 100 万レコードあたりの実行コストを設定してください",
  "{position}; {running} running, {queued} queued": "{position}。実行中 {running} 件、待機中 {queued} 件",
  "From the last {n} finished runs of {objects} {objects, plural, one {object} other {objects}}{delta}. A rule result, not a model's guess.": "{objects} 件のオブジェクトの直近 {n} 回の完了した実行から算出{delta}。モデルの推測ではなく、ルールの結果です。",
  ", changes only": "、変更分のみ",
  "No object of this system has a finished run to predict from yet.": "このシステムのオブジェクトには、予測に使える完了済みの実行がまだありません。",
  "{label}, queued, position {n}": "{label}、待機中、{n} 番目",
