  "Export load file hands the approved values over as a Migration Cockpit file instead of writing them live. It cannot be taken back.": "「ロードファイルをエクスポート」は、承認済みの値を直接書き込まずに Migration Cockpit のファイルとして引き渡します。取り消すことはできません。",
