  "{m} and {u}": "{m} と {u}",
  "The bars show how often a field agrees on pairs stewards accepted (dark) and rejected (light). A field that agrees on both separates nothing and earns little weight. Evidence weight is log2 of the two shares.": "バーは、スチュワードが承認したペア (濃) と却下したペア (淡) で項目が一致する頻度を示します。両方で一致する項目は区別に役立たず、重みは小さくなります。証拠の重みは 2 つの割合の log2 です。",
  "Calibration needs {n} accepted and {n} rejected steward decisions. Decide more pairs above and the weights are learned from them.": "キャリブレーションには、スチュワードの承認 {n} 件と却下 {n} 件が必要です。上でさらにペアを判断すると、そこから重みが学習されます。",
  "Apply the recommended weights": "推奨の重みを適用",
