  "An SAP BAdI, middleware or a pipeline posts up to {max} candidate records and gets back, at once, the enabled rules each one fails. A record with a failing critical rule is blocked. Nothing is stored except an audit entry, and no language model sees the records.": "SAP BAdI、ミドルウェア、パイプラインが最大{max}件の候補レコードを送ると、各レコードが違反した有効なルールがすぐに返ります。重大ルールに違反したレコードはブロックされます。保存されるのは監査エントリのみで、言語モデルがレコードを見ることはありません。",
