  "Each rule is dry-run on your latest extraction first. Only rules that hold on your data are promoted, and every promotion is audited and can be reverted.": "各ルールはまず最新の抽出データで試行されます。お客様のデータで成立するルールだけが昇格され、昇格はすべて監査記録に残り、元に戻せます。",
