  "{ready} ready to promote, {review} need review, {value} wait for a value set, {skipped} skipped.": "昇格可能 {ready} 件、要レビュー {review} 件、値セット待ち {value} 件、スキップ {skipped} 件。",
  "Promote when at least {pop}% of records fill the field, at most {fail} fail, and at least {n} records are checked.": "項目が入力されたレコードが {pop}% 以上、不合格が {fail} 以下、検査レコードが {n} 件以上のとき昇格します。",
