  "Usual range {lo} to {hi}, observed {o}": "通常の範囲 {lo} から {hi}、観測値 {o}",
  "The monitors could not be read.": "モニターを読み込めませんでした。",
  "{n, plural, =0 {No open break against the learned baseline} one {# open break against the learned baseline} other {# open breaks against the learned baseline}}": "{n, plural, =0 {学習済みベースラインに対する未対応の逸脱はありません} other {学習済みベースラインに対する未対応の逸脱が#件あります}}",
  "Each object is compared with its own earlier runs. With fewer than {n} earlier runs it only learns and raises nothing.": "各オブジェクトは自身の過去の実行と比較されます。過去の実行が{n}回未満の間は学習のみで、何も通知しません。",
  "What is learned": "学習した内容",
