  "No finished run yet.": "完了した実行はまだありません。",
  "Learned objects table, scrollable": "学習済みオブジェクトの表(スクロール可)",
  "Earlier runs used": "使用した過去の実行",
  "Breaks": "逸脱",
  "Run {n}": "実行 {n}",
  "{n} of {min} needed": "{min}回中{n}回",
  "Learning": "学習中",
  "Raises nothing until it has enough earlier runs.": "過去の実行が十分になるまで何も通知しません。",
  "Breaks in the latest run": "最新の実行での逸脱",
  "Most severe first.": "重大度の高い順。",
  "No break. Every watched figure is inside its usual range.": "逸脱はありません。監視中のすべての値が通常の範囲内です。",
  "Breaks table, scrollable": "逸脱の表(スクロール可)",
