  "Range chart": "範囲グラフ",
  "Why Aletheia flagged this": "Aletheiaがこれを検出した理由",
  "Worded by Aletheia from the figures only. It saw no record.": "Aletheiaが数値のみから作成した文章です。レコードは参照していません。",
  "Worded from the figures by a fixed template. No AI was used.": "数値から固定のテンプレートで作成した文章です。AIは使用していません。",
  "baseline median {m} over {n} earlier runs": "過去{n}回の実行によるベースライン中央値 {m}",
  "Runs behind it": "根拠となる実行",
