  "Only the first {n} records of each table and kind are kept; the counts above are complete.": "テーブルと種別ごとに先頭 {n} 件のみ保持します。上の件数は全件です。",
  "Withheld": "非表示",
  "Started automatically when the target system was analysed again.": "ターゲットシステムの再分析時に自動で開始しました。",
  "Since the comparison of {date}: {x} missing ({dx}), {w} fields differ ({dw}), {f} found ({df}).": "{date}の比較以降: 欠落 {x} 件({dx})、相違フィールド {w} 件({dw})、検出 {f} 件({df})。",
  "Compared against the files exported on {date}.": "{date}にエクスポートしたファイルと比較しました。",
  "Rebuilt from the current field mappings. No export snapshot was kept for this run, so a mapping changed after the load shows as a difference.": "現在のフィールドマッピングから再構築しました。この実行にはエクスポートのスナップショットが保存されていないため、ロード後に変更したマッピングは差異として表示されます。",
  "The export snapshot could not be used, so the expected side was rebuilt from the current field mappings.": "エクスポートのスナップショットを使用できなかったため、期待値は現在のフィールドマッピングから再構築しました。",
  "The latest export has no copy on file, so it is not the basis of this comparison.": "最新のエクスポートにはコピーが保存されていないため、この比較の基準にはなっていません。",
  "The suppression list drops an erased key from the extracts Meridian reads and stores. Some readers still see the old files: the change-detection baseline and the subject search read extract files directly. Erase the record in SAP as well, or the list is the only guard.": "抑止リストは、消去したキーをMeridianが読み込み保存する抽出から除外します。変更検知のベースラインと対象者検索は抽出ファイルを直接読むため、古いファイルが見える読み取り経路が残ります。SAPでも必ずレコードを消去してください。そうでなければこのリストが唯一の防御です。",
  "Lifted": "解除済み",
  "Key fields": "キー項目",
  "Keys": "キー数",
  "Rows dropped": "除外した行数",
  "Last dropped": "最終除外",
  "Lift": "解除",
  "Suppression list": "抑止リスト",
  "No suppressions yet.": "抑止はまだありません。",
  "Erased keys that extraction drops before findings, work records or files. The list holds a keyed hash, never the key. Lifting needs a reason and is audited.": "抽出が検出結果、作業レコード、ファイルより前に除外する消去済みキーです。リストが保持するのは鍵付きハッシュだけで、キー自体は保持しません。解除には理由が必要で、監査に記録されます。",
  "The suppression list": "抑止リスト",
