  "The lift failed.": "解除に失敗しました。",
  "the near-value search index is not built on this database": "近似値検索のインデックスがこのデータベースに作成されていません",
  "its tax or part number is too short or too long to compare": "税番号または部品番号が短すぎるか長すぎるため比較できません",
