  "Download a blank template": "空のテンプレートをダウンロード",
  "A blank template lists every field the object's rules read, with its description, whether it is required and its allowed values. The same name again is kept as a new version, with the column corrections carried over.": "空のテンプレートには、オブジェクトのルールが読み取るすべての項目が、説明、必須かどうか、許可値とともに一覧表示されます。同じ名前で再度アップロードすると新しいバージョンとして保存され、列の修正は引き継がれます。",
  "Your role cannot read the template library.": "あなたのロールではテンプレートライブラリを閲覧できません。",
  "The template library could not be read.": "テンプレートライブラリを読み込めませんでした。",
