  "Choose the field each unresolved column holds. Only fields of this object's tables are offered. A column left open is reported as absent.": "未解決の各列に対応する項目を選択してください。このオブジェクトのテーブルの項目のみが表示されます。未選択の列は欠落として報告されます。",
