  "SAProuter string (optional)": "SAProuter 文字列 (任意)",
  "Only when SAP is reached through a SAProuter, for example /H/router.example.com/S/3299/H/. Leave empty for a direct connection.": "SAProuter 経由で SAP に接続する場合のみ入力します (例: /H/router.example.com/S/3299/H/)。直接接続の場合は空欄のままにします。",
  "Secure Network Communications (SNC)": "Secure Network Communications (SNC)",
  "SNC partner name": "SNC パートナー名",
  "The SAP system's SNC name, for example p:CN=ECC, O=Company, C=ZA. Your Basis team has it.": "SAP システムの SNC 名です (例: p:CN=ECC, O=Company, C=ZA)。Basis チームに確認してください。",
  "Protection level": "保護レベル",
  "Own SNC name (optional)": "自身の SNC 名 (任意)",
  "Leave empty to use the name of the server's SNC credential.": "空欄の場合、サーバーの SNC 資格情報の名前を使用します。",
  "The SNC library path is set on the server (SNC_LIB). It is not entered here.": "SNC ライブラリのパスはサーバー側 (SNC_LIB) で設定します。ここでは入力しません。",
