  "The baseline runs did not vary, so no z can be computed. Any move past the minimum spread is a break.": "ベースライン実行に変動がないため z を計算できません。最小幅を超える変化はすべてブレイクです。",
  "Robust z {z}: the observed value is {z} scaled MADs from the baseline median. A break needs at least {k}.": "ロバスト z {z}: 観測値はベースライン中央値から {z} スケール MAD 離れています。ブレイクには {k} 以上が必要です。",
  "Robust z of at least {z}: the baseline runs could not be read, so the spread comes from the stored band. A break needs at least {k}.": "ロバスト z は {z} 以上: ベースライン実行を読み取れないため、ばらつきは保存済みのバンドから求めています。ブレイクには {k} 以上が必要です。",
