  "Failed runs": "失敗した実行",
  "A run ends in error.": "実行がエラーで終了します。",
  "The SLA sweep finds work past its acknowledge or resolve time.": "SLA チェックで、確認期限または解決期限を過ぎた作業が見つかります。",
  "Firewall rejections": "ファイアウォールの拒否",
  "The data quality firewall blocks records at entry. At most one message per object every 15 minutes.": "データ品質ファイアウォールが入力時にレコードをブロックします。メッセージはオブジェクトごとに 15 分に最大 1 件です。",
  "Configured": "設定済み",
  "Set MERIDIAN_SLACK_WEBHOOK_URL or MERIDIAN_TEAMS_WEBHOOK_URL in the server environment and restart Meridian. The address is a secret and is never shown here.": "サーバー環境で MERIDIAN_SLACK_WEBHOOK_URL または MERIDIAN_TEAMS_WEBHOOK_URL を設定し、Meridian を再起動してください。アドレスは機密情報であり、ここには表示されません。",
