  "The chat alert settings": "チャット通知の設定",
  "Check that each email domain has a mail server": "各メールドメインにメールサーバーがあるか確認する",
  "Asks this site's own DNS resolver, once per domain, at the next run. Only the domain is asked, never the address. When the resolver does not answer, no address fails.": "次回の実行時に、このサイト自身の DNS リゾルバーへドメインごとに一度だけ問い合わせます。問い合わせるのはドメインのみで、アドレスは送りません。リゾルバーが応答しない場合、アドレスは不合格になりません。",
  "Mail server check on from the next run": "メールサーバー確認は次回の実行から有効",
