  "{n, plural, one {# proposed fix waits} other {# proposed fixes wait}} in the cleansing queue.": "{n, plural, other {# 件の修正案}}がクレンジングキューで待機中です。",
  "Contact verification": "連絡先の検証",
  "Email syntax and disposable domains, phone numbers by country, and postal codes, cities and regions against the uploaded postal list. Everything runs on this site; no address leaves it.": "メールの構文と使い捨てドメイン、国ごとの電話番号、アップロードした郵便リストに対する郵便番号・市区町村・地域を確認します。すべてこのサイト内で実行され、アドレスが外部に出ることはありません。",
  "The contact verification results": "連絡先の検証結果",
  "Mail server check": "メールサーバー確認",
  "No contact results yet. They appear after the next run of business partner, customer or Employee Central.": "連絡先の結果はまだありません。ビジネスパートナー、得意先、または Employee Central の次回実行後に表示されます。",
  "Postal codes: a CSV with the columns country, postcode (the SAP country key), and optionally city and region, so address rules also check each record's city and region against its postal code. Bank codes: the licensed SWIFT BIC directory as CSV, BIC in the first column. An upload replaces the system's current list.": "郵便番号: country、postcode (SAP 国キー) の列と、任意で city と region の列を持つ CSV。これにより住所ルールは各レコードの市区町村と地域も郵便番号と照合します。銀行コード: ライセンス済み SWIFT BIC ディレクトリの CSV で、1 列目が BIC。アップロードするとシステムの現在のリストが置き換わります。",
  "Email, phone and address checks per rule, each failing record with its reason, and the mail server check.": "ルールごとのメール・電話・住所の確認、不合格レコードごとの理由、メールサーバー確認。",
