  "Accept {n} suggested values": "提案値 {n} 件を受け入れる",
  "{accepted} suggested values for {id} are in your fix batch. Nothing reaches SAP until an owner approves.": "{id} の提案値 {accepted} 件が修正バッチに入りました。オーナーが承認するまで SAP には届きません。",
  "Pick two different runs.": "異なる 2 つの実行を選択してください。",
