  "Inviting people needs the manage users permission. An administrator can invite them later.": "ユーザーを招待するには、ユーザー管理の権限が必要です。管理者が後で招待できます。",
  "Revoke the share link to {label}": "{label} への共有リンクを取り消す",
  "The link stops working at once. Anyone who opens it afterwards sees nothing; to share the page again, make a new link.": "リンクはすぐに使えなくなります。その後に開いた人には何も表示されません。ページを再び共有するには、新しいリンクを作成してください。",
  "End the out of office of {from_name}": "{from_name} の不在設定を終了する",
  "{to_name} stops covering the approvals and assigned work of {from_name} from now on.": "{to_name} は今後、{from_name} の承認と割り当て作業を代行しなくなります。",
  "Your comment of {created_at} is removed for everyone who reads this item.": "{created_at} のあなたのコメントは、この項目を読むすべての人に対して削除されます。",
  "You can't suspend or remove yourself.": "自分自身を停止または削除することはできません。",
  "This request is cancelled: its approval stops and nothing from it is sent to SAP.": "この依頼は取り消されます。承認は停止し、その内容は SAP に送信されません。",
  "The SLA policy for {what} is removed. Records that start their clock from now on use the default days.": "{what} の SLA ポリシーは削除されます。今後に期限の計測を始めるレコードは既定の日数を使います。",
  "The write-back of batch {label} stops. Records SAP has already committed stay committed; the records still waiting are not sent.": "バッチ {label} の書き戻しは停止します。SAP が既に確定したレコードは確定したままで、待機中のレコードは送信されません。",
  "The cost of waiting or the count of open critical issues could not be loaded, so the figures above may be missing.": "待機コストまたは未解決の重大な問題の件数を読み込めなかったため、上の数値が欠けている可能性があります。",
  "The run history could not be loaded.": "実行履歴を読み込めませんでした。",
  "The record of what was cleaned and what came back could not be loaded.": "クレンジングされた内容と再発した内容の記録を読み込めませんでした。",
  "The default {value} for {field} of {object} is removed. New create requests keep that field empty when the requester leaves it empty.": "{object} の {field} の既定値 {value} は削除されます。新しい作成依頼では、依頼者が空欄のままにするとその項目は空のままになります。",
  "The rule that sets {field} of {object} is removed. Requests saved from now on no longer get that value from it.": "{object} の {field} を設定するルールは削除されます。今後保存される依頼は、このルールから値を受け取りません。",
  "The write-backs waiting for a second approver could not be loaded.": "2 人目の承認者を待っている書き戻しを読み込めませんでした。",
  "Upload required": "アップロードが必要",
  "This table cannot be read from the system. Upload it as a file; its rules wait until then.": "このテーブルはシステムから読み取れません。ファイルとしてアップロードしてください。それまでルールは待機します。",
  "Preview source": "プレビューソース",
  "This source is a preview: its connector is not yet verified against a live tenant, so its rules wait and are left out of the score.": "このソースはプレビューです。コネクタが本番テナントでまだ検証されていないため、ルールは待機し、スコアから除外されます。",
  "No rules read it": "読み取るルールなし",
  "Read, but no rule checks this table yet, so it adds nothing to the score.": "読み取り済みですが、このテーブルを検査するルールがまだないため、スコアには影響しません。",
  "Not installed": "未インストール",
  "The component is not installed in this system, so its rules do not apply.": "このコンポーネントはこのシステムにインストールされていないため、ルールは適用されません。",
  "{module}: {count} {count, plural, one {rule waits} other {rules wait}} for data and {count, plural, one {is} other {are}} left out of the score.": "{module}: {count} 件のルールがデータ待ちで、スコアから除外されています。",
