  "The workbook lists every failing record of run {n} with the rule, the field and the value to correct. Fix the values in Excel and upload the workbook in the next step.": "ブックには実行 {n} の不合格レコードがすべて、ルール、項目、修正する値とともに載っています。Excel で値を修正し、次の手順でブックをアップロードしてください。",
  "What goes in the workbook": "ブックに含める内容",
