  "One workbook per owner": "担当者ごとに 1 冊",
  "Choosing a smaller workbook or one per owner is not offered by the server yet; the workbook holds every failing record.": "小さいブックや担当者ごとのブックはまだサーバーで選べません。ブックには不合格レコードがすべて含まれます。",
  "Making the workbook": "ブックを作成中",
  "Pull a run first.": "先に実行を取得してください。",
  "Download cleaning workbook": "クレンジング用ブックをダウンロード",
  "Only users with the export right can download the workbook.": "エクスポート権限のあるユーザーだけがブックをダウンロードできます。",
  "What is in the workbook": "ブックの内容",
  "One sheet per table. Each row is a record that fails at least one rule; the failing fields are marked and the rule and its description are beside them. Change only the values; keep the key columns as they are, so Meridian can match each row to its record.": "テーブルごとに 1 シートです。各行は 1 つ以上のルールに不合格のレコードで、不合格の項目に印があり、ルールとその説明が横にあります。値だけを変更し、キー列はそのままにしてください。Meridian が各行をレコードに照合できるようにするためです。",
  "Fix inside Meridian instead": "Meridian 内で修正する",
  "Persisting": "継続",
  "Nothing to compare yet": "まだ比較するものはありません",
  "This is the first run of {object}. Clean it and upload the workbook; the cleaned run is compared with this one.": "これは {object} の最初の実行です。クレンジングしてブックをアップロードすると、クレンジング済みの実行がこの実行と比較されます。",
