  "One of the runs has no score for this object.": "一方の実行にこのオブジェクトのスコアがありません。",
  "{new} new, {resolved} resolved, {regressed} regressed, {persisting} still failing": "新規 {new} 件、解決 {resolved} 件、悪化 {regressed} 件、継続中の不合格 {persisting} 件",
  "Which records": "対象レコード",
  "Record {key}, rule {rule}": "レコード {key}、ルール {rule}",
