  "The records could not be compared.": "レコードを比較できませんでした。",
  "No records in this group": "このグループにレコードはありません",
  "Pick another group above.": "上で別のグループを選んでください。",
  "Download workbook for the {n} new issues": "新規の問題 {n} 件のブックをダウンロード",
