  "The pull could not start.": "取得を開始できませんでした。",
  "Meridian reads {object} from {system} again and scores it. The new run appears in the run switcher.": "Meridian は {system} から {object} を再度読み取り、スコアを付けます。新しい実行は実行の切り替えに表示されます。",
  "This object has no run yet. The first pull sets the baseline every later run is compared with.": "このオブジェクトにはまだ実行がありません。最初の取得が、以後のすべての実行の比較基準になります。",
  "The pull finished. The new run is open.": "取得が完了しました。新しい実行を表示しています。",
