  "Only data stewards can pull a new run. Ask one to pull, or work on the latest run.": "新しい実行を取得できるのはデータスチュワードだけです。取得を依頼するか、最新の実行で作業してください。",
  "Pull {object} from {system}?": "{system} から {object} を取得しますか？",
