  "Scoring runs every rule of {object} on run {n}. A pull and an upload score on their own; score again after the rules change.": "スコアリングは実行 {n} に {object} のすべてのルールを適用します。取得とアップロードでは自動でスコアが付きます。ルールを変更した後は再度スコアリングしてください。",
  "Run {n} is being scored again.": "実行 {n} を再度スコアリング中です。",
  "Scoring could not start.": "スコアリングを開始できませんでした。",
  "The workbook could not be read.": "ブックを読み取れませんでした。",
  "Only users with the analyse right can upload a cleaned workbook.": "分析権限のあるユーザーだけがクレンジング済みブックをアップロードできます。",
